// Pure-virtual interface to be implemented by a server.
// This interface uses typed channels (i.e. |::fidl::ClientEnd<::fuchsia_net_interfaces::Watcher>|
// and |::fidl::ServerEnd<::fuchsia_net_interfaces::Watcher>|).
